"""Finite-memory information windows for tabular Q-learning.

Paper notation (N >= 1):
    h_t^N = { y_{[t-N, t]}, u_{[t-N, t-1]} }
with |D^N| = |Y|^{N+1} |U|^N when Y, U are finite.

For N = 0 the window is just the current observation y_t.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Sequence

import numpy as np


@dataclass(frozen=True)
class WindowSpec:
    """Dimensions of a finite observation/action alphabet and memory length."""

    n_y: int
    n_u: int
    N: int

    def __post_init__(self) -> None:
        if self.n_y < 1 or self.n_u < 1:
            raise ValueError("n_y and n_u must be >= 1")
        if self.N < 0:
            raise ValueError("memory N must be >= 0")

    @property
    def n_obs_slots(self) -> int:
        return self.N + 1

    @property
    def n_action_slots(self) -> int:
        return self.N

    @property
    def cardinality(self) -> int:
        """Number of distinct windows |D^N|."""
        if self.N == 0:
            return int(self.n_y)
        return int(self.n_y ** (self.N + 1) * self.n_u ** self.N)


class FiniteHistoryWindow:
    """Sliding window of quantized observation / action indices."""

    def __init__(self, spec: WindowSpec):
        self.spec = spec
        self.y_hist = np.full(spec.n_obs_slots, -1, dtype=np.int64)
        self.u_hist = np.full(max(spec.n_action_slots, 1), -1, dtype=np.int64)[: spec.n_action_slots]
        self._filled = 0  # number of observations seen so far

    def reset(self, y0: int) -> None:
        """Initialize with a single observation (and pad older slots with y0 / u=0)."""
        y0 = int(y0)
        if not (0 <= y0 < self.spec.n_y):
            raise ValueError(f"y0={y0} out of range [0, {self.spec.n_y})")
        self.y_hist[:] = y0
        if self.spec.N > 0:
            self.u_hist[:] = 0
        self._filled = 1

    def push(self, y_next: int, u: int) -> None:
        """Append action u then observation y_next (one environment step)."""
        y_next = int(y_next)
        u = int(u)
        if not (0 <= y_next < self.spec.n_y):
            raise ValueError(f"y_next={y_next} out of range [0, {self.spec.n_y})")
        if not (0 <= u < self.spec.n_u):
            raise ValueError(f"u={u} out of range [0, {self.spec.n_u})")

        if self.spec.N == 0:
            self.y_hist[0] = y_next
            self._filled = 1
            return

        # Drop oldest y and u; append new u then new y.
        self.y_hist[:-1] = self.y_hist[1:]
        self.y_hist[-1] = y_next
        self.u_hist[:-1] = self.u_hist[1:]
        self.u_hist[-1] = u
        self._filled = min(self._filled + 1, self.spec.n_obs_slots)

    @property
    def filled(self) -> int:
        return int(self._filled)

    def encode(self) -> int:
        """Map the current window to a unique integer in [0, |D^N|)."""
        return encode_window(self.y_hist, self.u_hist, self.spec)

    def as_arrays(self) -> tuple[np.ndarray, np.ndarray]:
        return self.y_hist.copy(), self.u_hist.copy()


def encode_window(y_hist: Sequence[int], u_hist: Sequence[int], spec: WindowSpec) -> int:
    """Encode observation/action index arrays into a flat window index."""
    y_hist = np.asarray(y_hist, dtype=np.int64).ravel()
    u_hist = np.asarray(u_hist, dtype=np.int64).ravel()
    if y_hist.shape[0] != spec.n_obs_slots:
        raise ValueError(f"expected {spec.n_obs_slots} observations, got {y_hist.shape[0]}")
    if u_hist.shape[0] != spec.n_action_slots:
        raise ValueError(f"expected {spec.n_action_slots} actions, got {u_hist.shape[0]}")

    if spec.N == 0:
        return int(y_hist[0])

    idx = 0
    for y in y_hist:
        idx = idx * spec.n_y + int(y)
    for u in u_hist:
        idx = idx * spec.n_u + int(u)
    return int(idx)


def decode_window(index: int, spec: WindowSpec) -> tuple[np.ndarray, np.ndarray]:
    """Inverse of encode_window."""
    index = int(index)
    if not (0 <= index < spec.cardinality):
        raise ValueError(f"index={index} out of range [0, {spec.cardinality})")

    if spec.N == 0:
        return np.array([index], dtype=np.int64), np.array([], dtype=np.int64)

    u_hist = np.empty(spec.N, dtype=np.int64)
    for k in range(spec.N - 1, -1, -1):
        u_hist[k] = index % spec.n_u
        index //= spec.n_u
    y_hist = np.empty(spec.N + 1, dtype=np.int64)
    for k in range(spec.N, -1, -1):
        y_hist[k] = index % spec.n_y
        index //= spec.n_y
    return y_hist, u_hist

"""Stage costs for information MDPs.

Matches the paper's structure
    rho(b, u) = lambda * r(b) + ||u||^2
without coupling to BeliefMDP_n_M.
"""

from __future__ import annotations

from typing import Literal

import numpy as np


def shannon_entropy(belief: np.ndarray) -> float:
    """H(b) = -sum_i b_i log b_i with 0 log 0 := 0."""
    b = np.asarray(belief, dtype=float).ravel()
    b = b[b > 0.0]
    if b.size == 0:
        return 0.0
    return float(-np.dot(b, np.log(b)))


def rao_entropy(belief: np.ndarray, distance_matrix: np.ndarray) -> float:
    """Rao / Wasserstein-style exploration cost b^T D b."""
    b = np.asarray(belief, dtype=float).ravel()
    D = np.asarray(distance_matrix, dtype=float)
    return float(b @ D @ b)


def control_effort(u: np.ndarray) -> float:
    """Paper stage effort: ||u||^2."""
    u = np.asarray(u, dtype=float).ravel()
    return float(np.dot(u, u))


def exploration_cost(
    belief: np.ndarray,
    *,
    kind: Literal["information gain", "wasserstein distance"] = "information gain",
    distance_matrix: np.ndarray | None = None,
) -> float:
    if kind == "information gain":
        return shannon_entropy(belief)
    if kind == "wasserstein distance":
        if distance_matrix is None:
            raise ValueError("distance_matrix required for wasserstein distance cost")
        return rao_entropy(belief, distance_matrix)
    raise ValueError(f"unknown exploration kind: {kind}")


def stage_cost(
    belief: np.ndarray,
    u: np.ndarray,
    *,
    lam: float = 1.0,
    kind: Literal["information gain", "wasserstein distance"] = "information gain",
    distance_matrix: np.ndarray | None = None,
) -> float:
    """rho(b, u) = lam * r(b) + ||u||^2."""
    return float(lam) * exploration_cost(
        belief, kind=kind, distance_matrix=distance_matrix
    ) + control_effort(u)

"""Factories for tiny known-pose mapping backends used by info-MDP experiments."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

import numpy as np

from ..classes.belief_mdp_n import BeliefMDP_n_Mapping
from ..classes.mapping import LandmarkMap
from ..classes.model import RangeBearingSensor, SingleIntegratorModel
from .window import WindowSpec


@dataclass
class MappingBackend:
    """Thin handle around BeliefMDP_n_Mapping for filter / alphabet access."""

    mdp: BeliefMDP_n_Mapping
    pose_n: int
    map_n: int
    obs_n: int
    action_n: int

    @property
    def n_y(self) -> int:
        return int(self.mdp.Y_n.shape[0])

    @property
    def n_u(self) -> int:
        return int(self.mdp.AQ.n_u)

    @property
    def len_M(self) -> int:
        return int(self.mdp.len_M)

    @property
    def Y_n(self) -> np.ndarray:
        Y = self.mdp.Y_n
        return Y.get() if hasattr(Y, "get") else np.asarray(Y)

    @property
    def U_n(self) -> np.ndarray:
        U = self.mdp.AQ.U
        return U.get() if hasattr(U, "get") else np.asarray(U)

    @property
    def X_n(self) -> np.ndarray:
        X = self.mdp.SQ.X_n
        return X.get() if hasattr(X, "get") else np.asarray(X)

    @property
    def Q_n(self) -> np.ndarray:
        Q = self.mdp.Q_n
        return Q.get() if hasattr(Q, "get") else np.asarray(Q)

    @property
    def all_maps(self) -> np.ndarray:
        M = self.mdp.all_maps_3d
        return M.get() if hasattr(M, "get") else np.asarray(M)

    def uniform_prior(self) -> np.ndarray:
        return np.full(self.len_M, 1.0 / self.len_M, dtype=float)

    def map_distance_matrix(self) -> np.ndarray:
        D = self.mdp._get_map_distance_matrix()
        return D.get() if hasattr(D, "get") else np.asarray(D)

    def window_spec(self, memory_N: int) -> WindowSpec:
        return WindowSpec(n_y=self.n_y, n_u=self.n_u, N=int(memory_N))

    def observation_index(self, y: np.ndarray) -> int:
        y = np.asarray(y, dtype=float).ravel()
        return int(self.mdp._find_observation_indices(y[np.newaxis, :])[0])

    def pose_index(self, x: np.ndarray) -> int:
        return int(self.mdp.SQ.get_quantized_index(np.asarray(x, dtype=float)))

    def filter_update(self, belief: np.ndarray, x: np.ndarray, y: np.ndarray) -> np.ndarray:
        """Bayesian map update F(b, x, y) using precomputed Q_n."""
        b = np.asarray(belief, dtype=float).ravel()
        y = np.asarray(y, dtype=float).ravel()
        x_idx = self.pose_index(x)
        y_idx = self.observation_index(y)
        q = np.maximum(self.Q_n[y_idx, x_idx, :], 1e-300)
        log_b = np.log(np.maximum(b, 1e-300))
        z = np.log(q) + log_b
        z -= z.max()
        b_new = np.exp(z)
        s = float(b_new.sum())
        if s <= 0.0:
            return self.uniform_prior()
        return b_new / s


def build_tiny_mapping_backend(
    *,
    pose_n: int = 2,
    map_n: int = 2,
    obs_n: int = 2,
    action_n: int = 2,
    num_landmarks: int = 1,
    sigma_r: float = 0.5,
    sigma_phi: float = 0.3,
    sigma_w: float = 0.1,
    r_max: float = 4.0,
    epsilon: float = 0.1,
    max_v: float = 4.0,
    dt: float = 1.0,
    exploration_type: str = "information gain",
) -> MappingBackend:
    """Build a small LandmarkMap + BeliefMDP_n_Mapping suitable for notebooks/tests."""
    landmark_map = LandmarkMap(
        x_min=0.0,
        x_max=10.0,
        y_min=0.0,
        y_max=10.0,
        n=map_n,
        num_landmarks=num_landmarks,
    )
    motion_model = SingleIntegratorModel(i_x=5.0, i_y=5.0, dt=dt, max_v=max_v)
    r0 = epsilon + 0.1 * (r_max - epsilon)
    r1 = epsilon + 0.9 * (r_max - epsilon)
    sensor = RangeBearingSensor(
        r_max=r_max,
        epsilon=epsilon,
        sigma_r=sigma_r,
        sigma_phi=sigma_phi,
        r0=r0,
        r1=r1,
    )
    cov_y = np.diag(np.tile([sigma_r**2, sigma_phi**2], num_landmarks))
    mdp = BeliefMDP_n_Mapping(
        n=pose_n,
        motion_model=motion_model,
        measurement_model=sensor,
        obstacles=[],
        _map=landmark_map,
        sigma_w=sigma_w,
        cov_y=cov_y,
        exploration_type=exploration_type,  # type: ignore[arg-type]
        obs_n=obs_n,
        action_n=action_n,
    )
    if mdp.Q_n is None:
        raise RuntimeError("Q_n was not computed; check observation quantization setup")
    if mdp.all_maps_3d is None:
        raise RuntimeError("all_maps_3d missing; map space may be too large")
    return MappingBackend(
        mdp=mdp,
        pose_n=pose_n,
        map_n=map_n,
        obs_n=obs_n,
        action_n=action_n,
    )


def to_numpy(x: Any) -> np.ndarray:
    return x.get() if hasattr(x, "get") else np.asarray(x)

"""Information MDP and its fixed-prior approximate finite-window model.

Exact model state: I_t = (b_{t-N}^-, h_t^N)
Approximate model state: hat{I}_t = (b^*, h_t^N) with effective state h_t^N only.
"""

from __future__ import annotations

from typing import Literal

import numpy as np

from .costs import stage_cost
from .factory import MappingBackend
from .window import FiniteHistoryWindow, WindowSpec, decode_window, encode_window


class InformationMDP:
    """Exact information MDP with evolving predictor b^- and finite window h.

    For known-pose mapping, Psi applies the map filter F along the window using
    the known pose trajectory aligned with the observations.
    """

    def __init__(
        self,
        backend: MappingBackend,
        memory_N: int,
        *,
        lam: float = 1.0,
        exploration_type: Literal["information gain", "wasserstein distance"] = "information gain",
    ):
        self.backend = backend
        self.spec = backend.window_spec(memory_N)
        self.lam = float(lam)
        self.exploration_type = exploration_type
        self._D = (
            backend.map_distance_matrix()
            if exploration_type == "wasserstein distance"
            else None
        )
        self.b_minus = backend.uniform_prior()
        self.window = FiniteHistoryWindow(self.spec)
        self.pose_hist = np.zeros((self.spec.n_obs_slots, backend.X_n.shape[1]), dtype=float)

    def reset(self, b_minus: np.ndarray | None, y0_idx: int, x0: np.ndarray) -> int:
        self.b_minus = (
            self.backend.uniform_prior()
            if b_minus is None
            else np.asarray(b_minus, dtype=float).ravel()
        )
        self.window.reset(y0_idx)
        x0 = np.asarray(x0, dtype=float).ravel()
        self.pose_hist[:] = x0
        return self.window.encode()

    def psi(
        self,
        b_prior: np.ndarray,
        y_hist: np.ndarray,
        pose_hist: np.ndarray,
    ) -> np.ndarray:
        """Psi(b_prior, h) via successive filter updates along the window."""
        b = np.asarray(b_prior, dtype=float).ravel()
        y_hist = np.asarray(y_hist, dtype=np.int64).ravel()
        pose_hist = np.asarray(pose_hist, dtype=float)
        if pose_hist.ndim == 1:
            pose_hist = pose_hist[np.newaxis, :]
        for k, y_idx in enumerate(y_hist):
            y = self.backend.Y_n[int(y_idx)]
            b = self.backend.filter_update(b, pose_hist[k], y)
        return b

    def belief(self) -> np.ndarray:
        return self.psi(self.b_minus, self.window.y_hist, self.pose_hist)

    def stage_cost(self, u_idx: int, belief: np.ndarray | None = None) -> float:
        b = self.belief() if belief is None else belief
        u = self.backend.U_n[int(u_idx)]
        return stage_cost(
            b,
            u,
            lam=self.lam,
            kind=self.exploration_type,
            distance_matrix=self._D,
        )

    def advance_predictor(self) -> None:
        """Update b^- after a filled window by absorbing the oldest (y,u,x)."""
        if self.spec.N == 0:
            # Predictor is unused for N=0; keep as current prior for API symmetry.
            return
        y_old = int(self.window.y_hist[0])
        x_old = self.pose_hist[0]
        self.b_minus = self.backend.filter_update(
            self.b_minus, x_old, self.backend.Y_n[y_old]
        )

    def push(self, y_idx: int, u_idx: int, x_next: np.ndarray) -> int:
        """Push one step into the window and return the new encoded state."""
        if self.spec.N > 0 and self.window.filled >= self.spec.n_obs_slots:
            self.advance_predictor()
        self.window.push(y_idx, u_idx)
        x_next = np.asarray(x_next, dtype=float).ravel()
        if self.spec.N == 0:
            self.pose_hist[0] = x_next
        else:
            self.pose_hist[:-1] = self.pose_hist[1:]
            self.pose_hist[-1] = x_next
        return self.window.encode()


class ApproximateInformationMDP:
    """Fixed-prior approximate information MDP: state is the finite window h only.

    Cost: hat{rho}(h, u) = rho(Psi(b^*, h), u)
    Transition is induced by the generative POMDP (see MappingInfoEnv).
    """

    def __init__(
        self,
        backend: MappingBackend,
        memory_N: int,
        b_star: np.ndarray | None = None,
        *,
        lam: float = 1.0,
        exploration_type: Literal["information gain", "wasserstein distance"] = "information gain",
    ):
        self.backend = backend
        self.spec = backend.window_spec(memory_N)
        self.b_star = (
            backend.uniform_prior()
            if b_star is None
            else np.asarray(b_star, dtype=float).ravel()
        )
        self.lam = float(lam)
        self.exploration_type = exploration_type
        self._D = (
            backend.map_distance_matrix()
            if exploration_type == "wasserstein distance"
            else None
        )

    @property
    def n_states(self) -> int:
        return self.spec.cardinality

    @property
    def n_actions(self) -> int:
        return self.spec.n_u

    def psi(self, y_hist: np.ndarray, pose_hist: np.ndarray) -> np.ndarray:
        b = np.asarray(self.b_star, dtype=float).ravel()
        y_hist = np.asarray(y_hist, dtype=np.int64).ravel()
        pose_hist = np.asarray(pose_hist, dtype=float)
        if pose_hist.ndim == 1:
            pose_hist = pose_hist[np.newaxis, :]
        for k, y_idx in enumerate(y_hist):
            y = self.backend.Y_n[int(y_idx)]
            b = self.backend.filter_update(b, pose_hist[k], y)
        return b

    def psi_from_index(self, h_idx: int, pose_hist: np.ndarray) -> np.ndarray:
        y_hist, _ = decode_window(h_idx, self.spec)
        return self.psi(y_hist, pose_hist)

    def stage_cost(self, h_idx: int, u_idx: int, pose_hist: np.ndarray) -> float:
        belief = self.psi_from_index(h_idx, pose_hist)
        u = self.backend.U_n[int(u_idx)]
        return stage_cost(
            belief,
            u,
            lam=self.lam,
            kind=self.exploration_type,
            distance_matrix=self._D,
        )

    def encode(self, y_hist: np.ndarray, u_hist: np.ndarray) -> int:
        return encode_window(y_hist, u_hist, self.spec)

    def decode(self, h_idx: int) -> tuple[np.ndarray, np.ndarray]:
        return decode_window(h_idx, self.spec)

